public class Main {
    // Retry amplification: every layer retries when the layer below fails
    static final int TRIES = 4;   // 1 first try + 3 retries
    static final int LAYERS = 3;  // edge -> service A -> service B -> database

    public static void main(String[] args) {
        long calls = 1; // calls arriving at the current layer per user request
        System.out.println("each layer makes " + TRIES + " attempts when the next hop fails");
        for (int layer = 1; layer <= LAYERS; layer++) {
            System.out.println("layer " + layer + " receives " + calls + " call(s)");
            calls *= TRIES; // every call below is multiplied by the attempts
        }
        System.out.println("database receives " + calls + " call(s)");
        // Retrying at one layer only keeps the multiplier at TRIES
        System.out.println("retry at one layer only: database receives " + TRIES);
    }
}

