public class Main {
    // AuthorizationPolicy order: DENY first, then ALLOW, otherwise default deny
    static String[] denies = {"dev/*"};
    static String[] allows = {"shop/web", "shop/admin"};

    static boolean match(String pattern, String principal) {
        if (principal.isEmpty()) return false; // plain-text caller has no identity
        if (pattern.endsWith("/*")) return principal.startsWith(pattern.substring(0, pattern.length() - 1));
        return principal.equals(pattern);
    }

    static String decide(String principal) {
        for (String p : denies) {              // 1. any matching DENY wins
            if (match(p, principal)) return "DENY";
        }
        if (allows.length == 0) return "ALLOW"; // 2. no ALLOW policy selects it
        for (String p : allows) {              // 3. must match at least one ALLOW
            if (match(p, principal)) return "ALLOW";
        }
        return "DENY";
    }

    public static void main(String[] args) {
        for (String who : new String[]{"shop/web", "dev/tool", "shop/batch", ""}) {
            System.out.println((who.isEmpty() ? "(plain text)" : who) + " -> " + decide(who));
        }
    }
}

