#include <bits/stdc++.h>
using namespace std;

// AuthorizationPolicy order: DENY first, then ALLOW, otherwise default deny
vector<string> denies = {"dev/*"};
vector<string> allows = {"shop/web", "shop/admin"};

bool match(const string& pattern, const string& principal) {
    if (principal.empty()) return false; // plain-text caller has no identity
    if (pattern.size() >= 2 && pattern.substr(pattern.size() - 2) == "/*")
        return principal.rfind(pattern.substr(0, pattern.size() - 1), 0) == 0;
    return principal == pattern;
}

string decide(const string& principal) {
    for (auto& p : denies)                 // 1. any matching DENY wins
        if (match(p, principal)) return "DENY";
    if (allows.empty()) return "ALLOW";    // 2. no ALLOW policy selects it
    for (auto& p : allows)                 // 3. must match at least one ALLOW
        if (match(p, principal)) return "ALLOW";
    return "DENY";
}

int main() {
    for (string who : {"shop/web", "dev/tool", "shop/batch", ""})
        cout << (who.empty() ? "(plain text)" : who) << " -> " << decide(who) << "\n";
    return 0;
}

