using System;

class Program
{
    // AuthorizationPolicy order: DENY first, then ALLOW, otherwise default deny
    static string[] denies = { "dev/*" };
    static string[] allows = { "shop/web", "shop/admin" };

    static bool Match(string pattern, string principal)
    {
        if (principal.Length == 0) return false; // plain-text caller has no identity
        if (pattern.EndsWith("/*")) return principal.StartsWith(pattern.Substring(0, pattern.Length - 1));
        return principal == pattern;
    }

    static string Decide(string principal)
    {
        foreach (string p in denies)               // 1. any matching DENY wins
            if (Match(p, principal)) return "DENY";
        if (allows.Length == 0) return "ALLOW";    // 2. no ALLOW policy selects it
        foreach (string p in allows)               // 3. must match at least one ALLOW
            if (Match(p, principal)) return "ALLOW";
        return "DENY";
    }

    static void Main()
    {
        foreach (string who in new string[] { "shop/web", "dev/tool", "shop/batch", "" })
            Console.WriteLine((who.Length == 0 ? "(plain text)" : who) + " -> " + Decide(who));
    }
}

