import java.util.*;

public class Main {
    // NetworkPolicy ingress model: a pod selected by any policy is isolated,
    // and only sources listed by a policy may reach it. Others stay open.
    static Map<String, List<String>> policies = new HashMap<>();

    static boolean allowed(String src, String dst) {
        if (!policies.containsKey(dst)) return true; // not selected by any policy: open
        return policies.get(dst).contains(src);      // isolated: only listed sources
    }

    public static void main(String[] args) {
        policies.put("api", List.of("web"));   // target -> allowed sources
        policies.put("db", List.of("api"));
        String[][] tests = {{"web", "api"}, {"web", "db"}, {"api", "db"}, {"db", "web"}, {"db", "api"}};
        for (String[] t : tests) {
            System.out.println(t[0] + " -> " + t[1] + ": " + (allowed(t[0], t[1]) ? "allow" : "deny"));
        }
    }
}

