// NetworkPolicy ingress model: a pod selected by any policy is isolated,
// and only sources listed by a policy may reach it. Others stay open.
map<string, vector<string>> policies = {{"api", {"web"}}, {"db", {"api"}}}; // target -> sources

bool allowed(const string& src, const string& dst) {
    auto it = policies.find(dst);
    if (it == policies.end()) return true;  // not selected by any policy: open
    return find(it->second.begin(), it->second.end(), src) != it->second.end(); // isolated
}

int main() {
    vector<pair<string, string>> tests = {{"web", "api"}, {"web", "db"}, {"api", "db"}, {"db", "web"}, {"db", "api"}};
    for (auto& t : tests)
        cout << t.first << " -> " << t.second << ": " << (allowed(t.first, t.second) ? "allow" : "deny") << "\n";
    return 0;
}

